WITH f AS (
  SELECT CAST('2022-01-01' AS DATE) AS d
  UNION ALL SELECT DATEADD(DAY,1,d) FROM f WHERE d < '2027-12-31'
)
INSERT INTO gold.dim_fecha
 (fecha_key, fecha_completa, anio, trimestre, trimestre_nombre, mes, mes_nombre, mes_corto,
  semana_anio, dia_mes, dia_semana, dia_nombre, es_fin_de_semana)
SELECT CONVERT(INT, CONVERT(CHAR(8), d, 112)), d, YEAR(d), DATEPART(QUARTER,d),
  CONCAT('T', DATEPART(QUARTER,d)), MONTH(d),
  CHOOSE(MONTH(d),'Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'),
  CHOOSE(MONTH(d),'Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'),
  DATEPART(ISO_WEEK,d), DAY(d),
  (DATEDIFF(DAY,'19000101',d) % 7) + 1,
  CHOOSE((DATEDIFF(DAY,'19000101',d) % 7) + 1,'Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'),
  CASE WHEN (DATEDIFF(DAY,'19000101',d) % 7) + 1 IN (6,7) THEN 1 ELSE 0 END
FROM f OPTION (MAXRECURSION 0);

